# Tables of the restructured manuscript (Task 42), written to paper_v3/generated as complete table floats.
#   - The old tables are regenerated by paper/make_tables_v2.py (imported, output redirected; code unchanged) and
#     compared with paper/generated/*.tex (generated/old_tables_check.txt).
#   - New main-text tables: t_data (T-1), t_clean (T-A), t_attn_attack (T-B), t_flip (T-C), t_attacks (T-D),
#     t_union_adaptive (T-F), t_per_class_v1 (T-G), t_neardup_compact (T-H). T-2 is the old t_constraints and T-E the
#     old t_dplus_ablation.
#   - New appendix tables: t_union_a8 (against the stand-in attacker A8), t_a8x_setting, t_a8x_tpr, t_runs,
#     t_standin, t_impl (implementation settings, macros only).
# Read-only on results/. Every number is read from a result file.
#
# Usage (from the project root): .venv\Scripts\python.exe paper_v3\gen\make_tables_v3.py
from datetime import date

import numpy as np
import pandas as pd

from common import A6X, A8X, CONTROLS, CTL_TYPE, GEN, OLD, SB, D, bounds, fmt, fmts, old_tables, rel

mt = old_tables()
tabular = mt.tabular
S8 = D.RES / "stage8"
YEARS = (2017, 2018)
SETS = [("lam1", r"$\lambda{=}1$"), ("lam100", r"$\lambda{=}100$"), ("norm_w0.5", "norm.")]


# ---------------------------------------------------------------- cell helpers

def m(v, d=3):
    return "n/a" if v is None or (isinstance(v, float) and np.isnan(v)) else f"${fmt(v, d)}$"


def ms(v, d=3):
    return f"${fmts(v, d)}$"


def mr(v, lo, hi, d=3):
    return f"${fmt(v, d)}$ {{\\scriptsize (${fmt(lo, d)}$ to ${fmt(hi, d)}$)}}"


def mrs(v, lo, hi, d=3):
    return mt.stack(f"${fmt(v, d)}$", f"{{\\scriptsize (${fmt(lo, d)}$ to ${fmt(hi, d)}$)}}")


def sci(v, lo, hi, d=3):
    return f"${fmts(v, d)}$ {{\\scriptsize [${bounds(lo, d)}$, ${bounds(hi, d)}$]}}"


def scis(v, lo, hi, d=3):
    return mt.stack(f"${fmts(v, d)}$", f"{{\\scriptsize [${bounds(lo, d)}$, ${bounds(hi, d)}$]}}")


def seeds(vals):
    return "$" + r"\,/\,".join(fmts(v) for v in vals) + "$"


def intc(v):
    return f"{int(v):,}".replace(",", "{,}")


def write(name, caption, label, colspec, header, rows, sources, notes=(), size="footnotesize", tabcolsep=None,
          resize=False, panels=None, place="t"):
    lines = [f"% Generated by paper_v3/gen/make_tables_v3.py on {date.today().isoformat()}. Do not edit.",
             *[f"% Source: {s}" for s in sources], f"\\begin{{table}}[{place}]", r"\centering", f"\\{size}"]
    if tabcolsep is not None:
        lines.append(f"\\setlength{{\\tabcolsep}}{{{tabcolsep}pt}}")
    lines += [f"\\caption{{{caption}}}", f"\\label{{{label}}}"]
    if panels:
        for i, (title, cs, hd, rw) in enumerate(panels):
            if i:
                lines.append(r"\par\medskip")
            lines.append(r"\textit{" + title + r"}\par\smallskip")
            lines += tabular(cs, hd, rw, resize)
    else:
        lines += tabular(colspec, header, rows, resize)
    if notes:
        lines.append(r"\par\smallskip\parbox{\linewidth}{\scriptsize " + " ".join(notes) + "}")
    lines += [r"\end{table}", ""]
    (GEN / f"{name}.tex").write_text("\n".join(lines), encoding="utf-8")
    print(f"wrote generated/{name}.tex")


def s5(yr, v, q, **f):
    x = D.sens("stage5")
    x = x[(x.dataset == yr) & (x.variant == v) & (x.quantity == q)]
    for k, val in f.items():
        x = x[x[k] == val]
    return x.value


# ---------------------------------------------------------------- T-1 datasets and performance

def t_data():
    d, rem = D.datasets()
    p = D.performance().set_index("dataset")
    classes = list(dict.fromkeys(list(d[d.dataset == "2017"]["class"]) + list(d[d.dataset == "2018"]["class"])))
    rows = []
    for c in classes:
        r = [D.CLASS_NAMES.get(c, mt.esc(c))]
        for yr in ("2017", "2018"):
            x = d[(d.dataset == yr) & (d["class"] == c)]
            r += [intc(x[k].iloc[0]) if len(x) else "removed" if (yr == "2018" and c in ("dos_slowhttptest", "ftp_patator"))
                  else "absent" for k in ("train", "val", "test")]
        rows.append(r)
    rows.append("MIDRULE")
    tot = ["Total"]
    for yr in ("2017", "2018"):
        x = d[d.dataset == yr]
        tot += [intc(x[k].sum()) for k in ("train", "val", "test")]
    rows += [tot, "MIDRULE", r"\multicolumn{7}{l}{\textit{Test macro-F1}} \\"]
    rows.append(["FT-Transformer"] + [r"\multicolumn{3}{c}{" + mr(p.loc[yr, "ftt_mean"], p.loc[yr, "ftt_min"],
                                                                     p.loc[yr, "ftt_max"], 4) + "}" for yr in ("2017", "2018")])
    rows[-1] = " & ".join(rows[-1]) + r" \\"
    rows.append(" & ".join(["XGBoost"] + [r"\multicolumn{3}{c}{" + m(p.loc[yr, "xgb"], 4) + "}" for yr in ("2017", "2018")])
                + r" \\")
    rows += ["MIDRULE", r"\multicolumn{7}{l}{\textit{Removed labels (rows before cleaning) and reason}} \\"]
    for _, r in rem.iterrows():
        rows.append(r"\multicolumn{7}{l}{" + f"{r.dataset}: {mt.esc(r.label)} (${intc(r.rows)}$ rows): {mt.esc(r.reason)}" + "} \\\\")
    write("t_data", "Datasets after cleaning (rows per class and split) and test macro-F1 of the models.", "t_data",
          "lrrrrrr", [["", r"\multicolumn{3}{c}{LYCOS-IDS2017}", r"\multicolumn{3}{c}{LycoS-Unicas-IDS2018}"],
                      ["Class", "Train", "Val", "Test", "Train", "Val", "Test"]], rows,
          ["results/stage1_class_counts.csv", "results/stage1_cleaning_report.csv",
           "results/stage7/stage7b_counts_by_step.csv"] + list(p.source),
          ["2017: temporal split per (label, day) group with gaps between splits. 2018: stratified random split (the "
           "file has no timestamps), with per-class caps applied before the split. Removed or absent classes are not "
           "modelled on that dataset. Macro-F1: FT-Transformer mean over 3 seeds (seed range), XGBoost one model; same "
           "training recipe on both datasets, no tuning on 2018."], resize="shrink")


# ---------------------------------------------------------------- T-A clean agreement and faithfulness (V1)

def t_clean():
    cv = pd.read_csv(S8 / "clean_variants.csv")
    cv = cv[cv.variant == "V1"]
    o = pd.read_csv(S8 / "clean_variants_ordering.csv").set_index(["variant", "metric"])
    names = {"attn_last": "Attn. last layer", "attn_mean": "Attn. layer mean", "attn_rollout": "Attn. rollout",
             "ig_zero": "IG", "gshap": "GradientSHAP", "occlusion": "Occlusion", "treeshap_xgb": "TreeSHAP (XGB)",
             "abs_x": r"$|x|$", "random": "Random"}

    def cell(yr, metric, meth, ref=None):
        x = cv[(cv.dataset == yr) & (cv.metric == metric) & (cv.method == meth)]
        x = x[x.ref == ref] if ref else x[x.ref.isna()]
        assert len(x) == 3, (yr, metric, meth, ref)
        return mr(x.value.mean(), x.value.min(), x.value.max())

    rows = [r"\multicolumn{5}{l}{\textit{Agreement: Spearman correlation between attention and attribution rankings}} \\"]
    for at in ("attn_rollout", "attn_mean", "attn_last"):
        for ref in (("ig_zero", "gshap", "occlusion", "treeshap_xgb") if at == "attn_rollout" else ("ig_zero",)):
            rows.append([f"{names[at]} vs {names[ref]}", cell(2017, "spearman", at, ref), cell(2018, "spearman", at, ref),
                         "", ""])
    meths = ["attn_rollout", "attn_mean", "attn_last", "ig_zero", "gshap", "occlusion", "abs_x", "random"]
    for metric, lab in (("del_auc", "Deletion AUC (train-mean masking; lower is more faithful; rank 1 = lowest)"),
                        ("ins_auc", "Insertion AUC (train-mean masking; higher is more faithful; rank 1 = highest)")):
        rows += ["MIDRULE", r"\multicolumn{5}{l}{\textit{" + lab + r"}} \\"]
        oo = o.loc[("V1", metric)]
        for meth in meths:
            rows.append([names[meth], cell(2017, metric, meth), cell(2018, metric, meth),
                         m(oo[f"rank2017_{meth}"], 0), m(oo[f"rank2018_{meth}"], 0)])
        rows.append(r"\multicolumn{3}{l}{\textit{Spearman of the method ordering, 2017 vs 2018}} & \multicolumn{2}{c}{"
                    + m(oo.spearman_orderings) + r"} \\")
    write("t_clean", "Clean data (V1, 7 common classes): agreement of attention with attribution methods, and deletion "
          "and insertion faithfulness of 8 explanation methods.", "t_clean", "lcccc",
          ["Quantity", "2017", "2018", "Rank 2017", "Rank 2018"], rows,
          ["results/stage8/clean_variants.csv", "results/stage8/clean_variants_ordering.csv"],
          ["Macro over the 7 common attack classes, mean over 3 seeds (seed range in brackets), V1 (explanation rows "
           "without a near duplicate in the training set). Ranks: position among the 8 methods from the 7-class means. "
           "Agreement of the layer-mean and last-layer attention with the other attributions, and all explanation rows "
           "(V0): Appendix~\\ref{sec:supp}."], resize="shrink")


# ---------------------------------------------------------------- T-B attention under constrained attacks (V1)

def t_attn_attack():
    def cell(yr, q, d=3, **f):
        x = s5(yr, "V1", q, **f)
        if yr == 2018:
            assert np.array_equal(x.sort_index().to_numpy(), s5(yr, "V0", q, **f).sort_index().to_numpy())
        assert len(x) == 3, (yr, q, f)
        return mr(x.mean(), x.min(), x.max(), d)

    rows = [r"\multicolumn{3}{l}{\textit{Top-10 rollout mass ratio, adversarial / clean (1 = unchanged)}} \\"]
    for atk, lab in (("A2", "A2 (attention only)"), ("A3_lam1000", r"A3 $\lambda{=}1000$ (evasion and attention)"),
                     ("A0", "A0 (random control)")):
        for e in ((1.0,) if atk == "A0" else (0.5, 1.0)):
            rows.append([f"{lab}, $\\epsilon = {fmt(e, 1)}$",
                         *[cell(yr, "mass_ratio_rollout", mode="constrained", attack=atk, eps=e) for yr in YEARS]])
    rows.append([r"A2 unconstrained reference, standardised $\epsilon = 0.5$",
                 *[cell(yr, "mass_ratio_rollout", mode="unconstrained", attack="A2", eps=0.5) for yr in YEARS]])
    rows += ["MIDRULE", r"\multicolumn{3}{l}{\textit{Evasion success, A1 minus A0}} \\"]
    for e in (0.5, 1.0):
        rows.append([f"$\\epsilon = {fmt(e, 1)}$", *[cell(yr, "A1_minus_A0_success", eps=e) for yr in YEARS]])
    write("t_attn_attack", r"Attention under protocol-constrained attacks (V1, 7 common classes).", "t_attn_attack",
          "lcc", ["Quantity", "2017", "2018"], rows, ["results/stage8/sensitivity_stage5.csv"],
          ["Macro over the 7 common classes, mean over 3 seeds (seed range). A2 keeps the prediction and minimises the "
           "rollout mass on the clean top-10 IG features; A3 also evades. The unconstrained reference has no feature "
           "constraints and an $L_\\infty$ budget in standardised units, so its budget is not in the units of the "
           "constrained attacks. On 2018 no source row is flagged, so V1 equals V0. Other budgets and A3 variants: "
           "Appendix~\\ref{sec:supp}."])


# ---------------------------------------------------------------- T-C faithfulness change by row status (V1)

def t_flip():
    d = pd.read_csv(S8 / "flip_split.csv")
    c = pd.read_csv(S8 / "flip_split_counts.csv")
    d = d[d.variant == "V1"]
    labs = {"ig_zero": "IG", "occlusion": "Occlusion", "attn_rollout": "Attn. rollout", "attn_mean": "Attn. layer mean",
            "attn_last": "Attn. last layer", "static_rollout": "Static rollout (class mean)",
            "static_ig": "Static IG (class mean)", "abs_x": r"$|x|$", "random": "Random"}
    cols = [("A1", "flipped"), ("A1", "not_flipped"), ("A0", "to_benign")]
    rows = []
    for meth, lab in labs.items():
        r = [lab]
        for yr in YEARS:
            for atk, sub in cols:
                x = d[(d.dataset == yr) & (d.attack == atk) & (d.subset == sub) & (d.method == meth)].aopc_gap_margin_minus_A0
                assert len(x) == 3
                r.append(mrs(x.mean(), x.min(), x.max(), 2) if meth in ("ig_zero", "occlusion", "attn_rollout", "attn_last")
                         else m(x.mean(), 2))
        rows.append(r)
    rows.append("MIDRULE")
    r = ["Rows per seed"]
    for yr in YEARS:
        for atk, sub in cols:
            x = c[(c.dataset == yr) & (c.variant == "V1") & (c.attack == atk) & (c.subset == sub)].sort_values("seed").n_rows
            r.append(mt.stack(*[str(int(v)) for v in x]) if False else ", ".join(str(int(v)) for v in x))
    rows.append(r)
    hd = [["", r"\multicolumn{3}{c}{2017}", r"\multicolumn{3}{c}{2018}"],
          ["Ranking"] + [mt.stack("A1", "flipped"), mt.stack("A1 not", "flipped"), mt.stack("A0", "flipped")] * 2]
    write("t_flip", r"Change of the margin AOPC gap minus the A0 change at $\epsilon = 1$, by row status (V1).", "t_flip",
          "lcccccc", hd, rows, ["results/stage8/flip_split.csv", "results/stage8/flip_split_counts.csv"],
          ["Change of the margin AOPC gap from the clean to the adversarial row, minus the mean change over all A0 rows "
           "at the same budget; train-mean masking; macro over classes, mean over seeds (seed range for IG, occlusion, "
           "rollout and last-layer attention). More negative = larger loss of faithfulness. A0 flipped: rows that the "
           "random control flipped to benign by chance. 2017: 7 common classes."], resize="shrink", tabcolsep=4)


# ---------------------------------------------------------------- T-D success and undetected per attack (V1)

def t_attacks():
    de = D.sens("defenders")
    de = de[de.seed_only.isna() & (de.variant == "V1")]
    pa = D.sens("paired")
    pa = pa[pa.variant == "V1"]
    tp = pd.read_csv(A8X / "summary_tpr.csv")
    tp = tp[tp.rowset == "V1"]
    ex = pd.read_csv(A8X / "summary_extra.csv")
    ex = ex[(ex.part == "a") & (ex.rowset == "V1")]
    panels = []
    for yr in YEARS:
        rows = []
        for atk, lab, aim, kind in [("A1", "A1", "none", "")] + \
                [(a, D.ATTACK_NAMES[a], "D", "exact") for a in D.A6N] + \
                [(a, D.ATTACK_NAMES[a], r"D$_+$", "stand-in") for a in D.A8N]:
            x = de[(de.dataset == yr) & (de.attack == atk)].iloc[0]
            p = pa[(pa.dataset == yr) & (pa.attack == atk)]
            rows.append([lab, aim, kind, mr(x.success, x.success_lo, x.success_hi), mr(x.undet_D, x.undet_D_lo, x.undet_D_hi),
                         mr(x.undet_Dplus, x.undet_Dplus_lo, x.undet_Dplus_hi),
                         sci(p.tpr_diff.iloc[0], p.tpr_diff_lo.iloc[0], p.tpr_diff_hi.iloc[0]) if atk != "A1" else
                         sci(p.tpr_diff.iloc[0], p.tpr_diff_lo.iloc[0], p.tpr_diff_hi.iloc[0])])
        for st, lab in SETS:
            e = ex[(ex.year == yr) & (ex.setting == st)]
            ep, es = e[e.seeds == "pooled"].iloc[0], e[e.seeds != "pooled"]
            t = tp[(tp.year == yr) & (tp.attack == f"A8x_{st}")].iloc[0]
            assert abs(t.success - ep.A8x_success) < 1e-12 and abs(t.undet_Dplus - ep.A8x_undetDplus_share_of_source) < 1e-12
            rows.append([f"A8x {lab}", r"D$_+$", "exact obj.", mr(ep.A8x_success, es.A8x_success.min(), es.A8x_success.max()),
                         mr(ep.A8x_undetD_share_of_source, es.A8x_undetD_share_of_source.min(), es.A8x_undetD_share_of_source.max()),
                         mr(ep.A8x_undetDplus_share_of_source, es.A8x_undetDplus_share_of_source.min(),
                             es.A8x_undetDplus_share_of_source.max()),
                         sci(t.tpr_diff, t.tpr_diff_lo, t.tpr_diff_hi)])
        panels.append((f"{yr}", "lllcccc", ["Attack", "Aimed at", "Attacker", "Success", "Undet. D", r"Undet. D$_+$",
                                             r"TPR D$_+$ minus D [95\% CI]"], rows))
    write("t_attacks", r"Success and undetected share per attack at $\epsilon = 1$ (V1, 7 common classes), and the paired "
          r"TPR difference D$_+$ minus D on the flipped rows of each attack.", "t_attacks", None, None, None,
          ["results/stage8/sensitivity_defenders.csv", "results/stage8/sensitivity_paired.csv",
           rel(A8X / "summary_tpr.csv"), rel(A8X / "summary_extra.csv")],
          ["Success: share of source rows predicted benign; Undet.: also below the detector threshold at 5\\% FPR on "
           "validation benign rows. Mean over seeds pooled over rows (seed range). TPR difference: paired bootstrap over "
           "the flipped rows (1,000 draws). Attacker: exact, the attacker's objective is the exact detector score; "
           "stand-in, differentiable stand-ins for the consistency scores; exact obj., the exact score with surrogate "
           "gradients for the eight rank-based scores. The rows of an attack aimed at D$_+$ were optimised against "
           "D$_+$, so a negative TPR difference on them is expected by construction; the equal-effort comparison is "
           "Table~\\ref{t_union_adaptive}."], resize="shrink", tabcolsep=4, panels=panels)


# ---------------------------------------------------------------- T-F equal-effort union, adaptive (headline)

def t_union_adaptive():
    ax = pd.read_csv(A8X / "summary_union.csv")
    sx = pd.read_csv(A6X / "summary_union.csv")
    sb = pd.read_csv(SB / "summary_union.csv")
    ex = pd.read_csv(A8X / "summary_extra.csv")
    ex = ex[ex.part == "b"]
    panels = []

    def pick(df, yr, **f):
        x = df[(df.year == yr) & (df.rowset == "V1")]
        for k, v in f.items():
            x = x[x[k].str.startswith(v)] if isinstance(v, str) and k == "union" else x[x[k] == v]
        return x[x.seeds == "pooled"].iloc[0], x[x.seeds != "pooled"].sort_values("seeds")

    for yr in YEARS:
        rq = {}
        for c in ("a1", "a2"):
            s = pd.read_csv(SB / str(yr) / "standin_quality.csv")
            r2 = s[s.control == c].r2
            rq[c] = f"stand-in ($R^2$ ${fmt(r2.median())}$ / ${fmt(r2.min())}$)"
        h, hs = pick(ax, yr, union="headline:")
        a, as_ = pick(ax, yr, union="Stage A:")
        g, gs = pick(sx, yr, union="selection effect on D:")
        rows = [["D", r"A1 + A6 $\times 3$", "exact", m(h.undet_D), "(reference)", "", ms(-h.Dplus_minus_D) + " " +
                 f"{{\\scriptsize [${bounds(-h.hi)}$, ${bounds(-h.lo)}$]}}"],
                ["D", r"A1 + A6x $\times 3$", "exact", m(g.undet_second), sci(g.second_minus_first, g.lo, g.hi),
                 seeds(gs.second_minus_first), ""],
                [r"\textbf{D$_+$}", r"\textbf{A1 + A8x $\times 3$}", "exact obj.", m(h.undet_Dplus),
                 r"\textbf{" + sci(h.Dplus_minus_D, h.lo, h.hi) + "}", seeds(hs.Dplus_minus_D), "(reference)"],
                [r"D$_+$", r"A1 + A8 $\times 3$", "stand-in", m(a.undet_Dplus), sci(a.Dplus_minus_D, a.lo, a.hi),
                 seeds(as_.Dplus_minus_D), ""], "MIDRULE"]
        assert abs(g.undet_first - h.undet_D) < 1e-12
        for c in CONTROLS:
            p, ps = pick(sb, yr, control=c)
            assert abs(p.undet_D - h.undet_D) < 1e-12
            e, es = pick(ex, yr, control=c)
            rows.append([c, r"A1 + own $\times 3$", "exact" if CTL_TYPE[c] == "exact" else rq[c], m(p.undet_control),
                         sci(p.control_minus_D, p.cmD_lo, p.cmD_hi), seeds(ps.control_minus_D),
                         sci(e.control_minus_Dplus, e.lo, e.hi)])
        rows.append(["b", r"\multicolumn{6}{l}{not attacked adaptively (Section~\ref{sec:limitations})} \\"])
        rows[-1] = " & ".join(rows[-1])
        panels.append((f"{yr}, V1 ({intc(h.n_rows / 3)} source rows per seed)", "lllcccc",
                       ["Detector", "Attacker", "Type", "Undet.", r"Minus D [95\% CI]", "Seeds 0 / 1 / 2",
                        r"Minus D$_+$ (A8x) [95\% CI]"], rows))
    write("t_union_adaptive", r"Equal-effort union at $\epsilon = 1$ (V1): share of source rows that are successful and "
          r"undetected, each detector against its own attackers.", "t_union_adaptive", None, None, None,
          [rel(A8X / "summary_union.csv"), rel(A6X / "summary_union.csv"), rel(SB / "summary_union.csv"),
           rel(A8X / "summary_extra.csv"), "results/stage9/adaptive/{2017,2018}/standin_quality.csv"],
          ["A source row counts if any candidate aimed at that detector flips it to benign and stays below the detector's "
           "threshold (5\\% FPR). Minus D: difference to D under A1 + A6 $\\times 3$ (for the A6x row: D under A6x minus "
           "D under A6); a positive value means more rows evade undetected, which is worse for the defender. Paired "
           "bootstrap over source rows within seed, 1,000 draws; the interval does not capture variation between seeds. "
           "Type: exact, the attacker optimises the exact score; exact obj., the exact score with surrogate gradients "
           "for the eight rank-based consistency scores; stand-in, differentiable stand-ins ($R^2$ median / minimum over "
           "features and seeds). Comparisons of a1 or a2 with D$_+$ under A8x are not at equal attacker strength. The "
           "D$_+$ row with A8 is shown for comparison only."], resize="shrink", tabcolsep=3, panels=panels)


# ---------------------------------------------------------------- T-G per-class (V1)

def t_per_class_v1():
    from src.stage9_dplus_ablation import keep_pos
    pc = D.sens("per_class")
    pc = pc[(pc.variant == "V1") & (pc.eps == 1.0) & (pc.attack == "A6_lam1")]
    cells = {}
    for yr in YEARS:
        kp = keep_pos(str(yr), "V1")
        per = []
        for s in D.SEEDS:
            r = pd.read_parquet(A8X / str(yr) / f"seed{s}" / "rows_A8x_lam1.parquet")
            r = r[r.pos.isin(kp)]
            u = (r.flipped & (r.score_Dplus < r.thr_Dplus)).groupby(r["class"]).agg(["mean", "size"])
            per.append(u.assign(seed=s))
        cells[yr] = pd.concat(per)
    rows = []
    for c in D.COMMON:
        r = [D.CLASS_NAMES[c]]
        for yr in YEARS:
            x = pc[(pc.dataset == yr) & (pc["class"] == c)]
            if len(x):
                x = x.iloc[0]
                lo, hi = mt.split_range(x.seed_range_succ_undet_D)
                r.append(mrs(x.succ_undet_D, lo, hi))
            else:
                r.append("n/a")
            y = cells[yr].loc[[c]] if c in cells[yr].index else None
            if y is not None:
                assert y["size"].nunique() == 1
                r.append(mrs((y["mean"] * y["size"]).sum() / y["size"].sum(), y["mean"].min(), y["mean"].max()))
                n = int(y["size"].iloc[0])
                r.append(f"{n}" + (r"$^\ast$" if n < 100 else ""))
            else:
                r += ["n/a", "0"]
        rows.append(r)
    write("t_per_class_v1", r"Per-class share of successful and undetected source rows at $\epsilon = 1$ (V1): A6 "
          r"$\lambda{=}1$ against D and A8x $\lambda{=}1$ against D$_+$.", "t_per_class_v1", "lcccccc",
          [["", r"\multicolumn{3}{c}{2017}", r"\multicolumn{3}{c}{2018}"],
           ["Class", "A6 vs D", r"A8x vs D$_+$", "n", "A6 vs D", r"A8x vs D$_+$", "n"]], rows,
          ["results/stage8/sensitivity_per_class.csv", "results/stage9/a8x/{2017,2018}/seed*/rows_A8x_lam1.parquet",
           "src/stage9_dplus_ablation.py keep_pos (V1 rows)"],
          ["Mean over seeds pooled over rows (seed range). n: V1 source rows per seed; $^\\ast$ marks n < 100. Single "
           "attacks, not the union. All source rows (V0) with A8 in Appendix~\\ref{sec:supp}."], tabcolsep=4,
          resize="shrink")


# ---------------------------------------------------------------- T-H near-duplicate sensitivity, headline quantities

def t_neardup_compact():
    de = D.sens("defenders")
    de = de[de.seed_only.isna()]
    pa = D.sens("paired")
    ax = pd.read_csv(A8X / "summary_union.csv")
    tp = pd.read_csv(A8X / "summary_tpr.csv")
    V = ["V0", "V1", "V2"]
    rows = []

    def add(label, fn):
        rows.append([label] + [fn(yr, v) for yr in YEARS for v in V])

    def s5c(q, d=3, **f):
        def g(yr, v):
            x = s5(yr, v, q, **f)
            return mr(x.mean(), x.min(), x.max(), d) if False else m(x.mean(), d)
        return g
    add(r"A2 mass ratio, $\epsilon = 1$", s5c("mass_ratio_rollout", mode="constrained", attack="A2", eps=1.0))
    add("Flipped A1, AOPC gap minus A0, IG", s5c("aopc_gap_margin_flipped_minus_A0", d=2, eps=1.0, method="ig_zero"))
    add("Flipped A1, AOPC gap minus A0, rollout", s5c("aopc_gap_margin_flipped_minus_A0", d=2, eps=1.0, method="attn_rollout"))
    add(r"Undet.\ D, A6 $\lambda{=}1$", lambda yr, v: m(de[(de.dataset == yr) & (de.variant == v)
                                                          & (de.attack == "A6_lam1")].undet_D.iloc[0]))
    add(r"TPR D$_+$ minus D, A6 $\lambda{=}1$ rows", lambda yr, v: ms(pa[(pa.dataset == yr) & (pa.variant == v)
                                                                         & (pa.attack == "A6_lam1")].tpr_diff.iloc[0]))
    add(r"TPR D$_+$ minus D, A8x $\lambda{=}1$ rows", lambda yr, v: ms(tp[(tp.year == yr) & (tp.rowset == v)
                                                                          & (tp.attack == "A8x_lam1")].tpr_diff.iloc[0]))

    def un(lab):
        def g(yr, v):
            x = ax[(ax.year == yr) & (ax.rowset == v) & ax.union.str.startswith(lab) & (ax.seeds == "pooled")].iloc[0]
            return scis(x.Dplus_minus_D, x.lo, x.hi)
        return g
    add(r"Union D$_+$ (A8x) minus D", un("headline:"))
    add(r"Union D$_+$ (A8, stand-in) minus D", un("Stage A:"))
    write("t_neardup_compact", "Near-duplicate sensitivity of the headline quantities: all source rows (V0), near "
          "duplicates removed (V1, primary), DoS Slowloris and web attack removed (V2).", "t_neardup_compact", "lcccccc",
          [["", r"\multicolumn{3}{c}{2017}", r"\multicolumn{3}{c}{2018}"], ["Quantity"] + V * 2], rows,
          ["results/stage8/sensitivity_stage5.csv", "results/stage8/sensitivity_defenders.csv",
           "results/stage8/sensitivity_paired.csv", rel(A8X / "summary_union.csv"), rel(A8X / "summary_tpr.csv")],
          ["Means over seeds (attacks) or pooled over rows (detectors); union with the paired bootstrap 95\\% CI. "
           "Rows are filtered after the fact; models, attacks and detectors are unchanged. On 2018 no source row is "
           "flagged, so V1 equals V0. Full tables in Appendix~\\ref{sec:sens}."], resize="shrink", tabcolsep=4)


# ---------------------------------------------------------------- appendix D: against the stand-in attacker A8

def t_union_a8():
    ax = pd.read_csv(A8X / "summary_union.csv")
    sb = pd.read_csv(SB / "summary_union.csv")
    rows = []
    for yr in YEARS:
        for v in ("V0", "V1", "V2"):
            x = ax[(ax.year == yr) & (ax.rowset == v) & ax.union.str.startswith("Stage A:")]
            p, s = x[x.seeds == "pooled"].iloc[0], x[x.seeds != "pooled"].sort_values("seeds")
            rows.append([str(yr), v, m(p.undet_D), m(p.undet_Dplus), sci(p.Dplus_minus_D, p.lo, p.hi), seeds(s.Dplus_minus_D)])
        rows.append("MIDRULE")
    rows = rows[:-1]
    crow = []
    for yr in YEARS:
        for c in CONTROLS:
            x = sb[(sb.year == yr) & (sb.rowset == "V1") & (sb.control == c)]
            p, s = x[x.seeds == "pooled"].iloc[0], x[x.seeds != "pooled"].sort_values("seeds")
            crow.append([str(yr), c, CTL_TYPE[c], m(p.undet_control), m(p.undet_Dplus),
                         sci(p.control_minus_Dplus, p.cmDp_lo, p.cmDp_hi), seeds(s.control_minus_Dplus)])
        crow.append("MIDRULE")
    crow = crow[:-1]
    write("t_union_a8", r"Against the stand-in attacker A8: equal-effort union with D$_+$ facing A1 + A8 $\times 3$ "
          r"($\epsilon = 1$), and the controls compared with D$_+$ under A8.", "t_union_a8", None, None, None,
          [rel(A8X / "summary_union.csv"), rel(SB / "summary_union.csv")],
          ["D faces A1 + A6 $\\times 3$. Paired bootstrap over source rows within seed (1,000 draws). These comparisons "
           "use the stand-in attacker A8 for D$_+$; against the exact-objective attacker A8x the sign of D$_+$ minus D "
           "reversed (Table~\\ref{t_union_adaptive}), so the control minus D$_+$ values here are not the comparison at "
           "the stronger attacker."], resize="shrink", tabcolsep=4,
          panels=[(r"D$_+$ minus D, D$_+$ against A8", "llcccc", ["Dataset", "Rows", "Undet. D", r"Undet. D$_+$",
                                                                  r"D$_+$ minus D [95\% CI]", "Seeds 0 / 1 / 2"], rows),
                  (r"Control minus D$_+$, D$_+$ against A8 (V1)", "lllcccc",
                   ["Dataset", "Control", "Attacker", "Undet. control", r"Undet. D$_+$", r"Minus D$_+$ [95\% CI]",
                    "Seeds 0 / 1 / 2"], crow)])


def t_a8x_setting():
    ax = pd.read_csv(A8X / "summary_union.csv")
    sx = pd.read_csv(A6X / "summary_union.csv")
    rows = []
    labs = [("per setting lam1:", r"A8x $\lambda{=}1$ vs A6 $\lambda{=}1$", ax),
            ("per setting lam100:", r"A8x $\lambda{=}100$ vs A6 $\lambda{=}100$", ax),
            ("per setting norm_w0.5:", "A8x norm. vs A6 norm.", ax),
            ("sensitivity", r"Unequal effort: D$_+$ faces A1 + A8 $\times 3$ + A8x $\times 3$", ax),
            ("headline:", r"A6x headline: D faces A1 + A6x $\times 3$", sx),
            ("sensitivity", r"Unequal effort: D faces A1 + A6 $\times 3$ + A6x $\times 3$", sx)]
    for yr in YEARS:
        for lab, txt, df in labs:
            x = df[(df.year == yr) & (df.rowset == "V1") & df.union.str.startswith(lab)]
            p, s = x[x.seeds == "pooled"].iloc[0], x[x.seeds != "pooled"].sort_values("seeds")
            col = "Dplus_minus_D" if df is ax else "second_minus_first"
            rows.append([str(yr), txt, sci(p[col], p.lo, p.hi), seeds(s[col])])
        rows.append("MIDRULE")
    rows = rows[:-1]
    write("t_a8x_setting", r"D$_+$ minus D under A8x per attack setting, the unequal-effort sensitivity unions and the "
          r"A6x union (V1, $\epsilon = 1$).", "t_a8x_setting", "llcc",
          ["Dataset", "Union", r"D$_+$ minus D [95\% CI]", "Seeds 0 / 1 / 2"], rows,
          [rel(A8X / "summary_union.csv"), rel(A6X / "summary_union.csv")],
          ["Per setting: D faces A1 and one A6 setting, D$_+$ faces A1 and the same A8x setting. Unequal effort: one "
           "side has twice as many candidates (marked); not a headline comparison. A6x: the A6 attack on D with the "
           "selection key of A8x (Section~\\ref{sec:a6x}); separate bootstrap draws, so its interval can differ from the "
           "headline in the last digit."], resize="shrink", tabcolsep=4)


def t_a8x_tpr():
    tp = pd.read_csv(A8X / "summary_tpr.csv")
    order = ["A8x_lam1", "A8x_lam100", "A8x_norm_w0.5", "A8_lam1", "A8_lam100", "A8norm_w0.5"]
    lab = {"A8x_lam1": r"A8x $\lambda{=}1$", "A8x_lam100": r"A8x $\lambda{=}100$", "A8x_norm_w0.5": "A8x norm.",
           "A8_lam1": r"A8 $\lambda{=}1$", "A8_lam100": r"A8 $\lambda{=}100$", "A8norm_w0.5": "A8 norm."}
    rows = []
    for yr in YEARS:
        for a in order:
            x = tp[(tp.year == yr) & (tp.attack == a)].set_index("rowset")
            rows.append([str(yr), lab[a], m(x.loc["V1", "success"]), m(x.loc["V1", "undet_Dplus"])]
                        + [scis(x.loc[v, "tpr_diff"], x.loc[v, "tpr_diff_lo"], x.loc[v, "tpr_diff_hi"]) for v in ("V0", "V1", "V2")]
                        + [scis(x.loc["V1", "auroc_diff"], x.loc["V1", "auroc_diff_lo"], x.loc["V1", "auroc_diff_hi"])])
        rows.append("MIDRULE")
    rows = rows[:-1]
    write("t_a8x_tpr", r"Paired TPR and AUROC differences D$_+$ minus D on the rows of A8x and A8 ($\epsilon = 1$).",
          "t_a8x_tpr", "llcccccc",
          [["", "", r"\multicolumn{2}{c}{V1}", r"\multicolumn{3}{c}{TPR difference [95\% CI]}", "AUROC diff."],
           ["Dataset", "Attack", "Success", r"Undet. D$_+$", "V0", "V1", "V2", "V1"]], rows,
          [rel(A8X / "summary_tpr.csv")],
          ["TPR on the flipped rows at each detector's 5\\% FPR threshold; AUROC against the benign test negatives; "
           "paired bootstrap, 1,000 draws. Both attacks were aimed at D$_+$, so negative values are expected by "
           "construction and are not evidence on their own. A8 intervals here come from the same pipeline as A8x and "
           "can differ in the last digit from Table~\\ref{t_attacks}."], resize="shrink", tabcolsep=3)


