def t_standin():
    feats = ["rollout_gxi_spearman", "rollout_gxi_jacc10", "rollout_gxi_cos", "rollout_ig20_spearman",
             "rollout_ig20_jacc10", "rollout_ig20_cos", "attnmean_gxi_spearman", "attnmean_gxi_jacc10",
             "attnmean_gxi_cos", "attnmean_ig20_spearman", "attnmean_ig20_jacc10", "attnmean_ig20_cos"]
    a8 = {2017: pd.read_csv(S8 / "stage8c_standin_quality_2017.csv"),
          2018: pd.read_csv(D.RES / "stage7" / "stage7e" / "standin_quality.csv")}
    sbq = {yr: pd.read_csv(SB / str(yr) / "standin_quality.csv") for yr in YEARS}
    rows = []
    for k, f in enumerate(feats):
        r = [mt.esc(f).replace(r"\_", " ")]
        for yr in YEARS:
            r.append(m(a8[yr][a8[yr].feature == f].r2.mean()))
        for c in ("a1", "a2"):
            for yr in YEARS:
                s = sbq[yr]
                x = s[(s.control == c) & (s.feature == f"x{k}")]
                assert len(x) == 3
                r.append(m(x.r2.mean()))
        rows.append(r)
    rows.append("MIDRULE")
    med = ["Median / min over features and seeds"]
    for yr in YEARS:
        x = a8[yr].r2
        med.append(f"${fmt(x.median())}$ / ${fmt(x.min())}$")
    for c in ("a1", "a2"):
        for yr in YEARS:
            x = sbq[yr][sbq[yr].control == c]
            x = x[x.feature.str.startswith("x")].r2
            med.append(f"${fmt(x.median())}$ / ${fmt(x.min())}$")
    rows.append(med)
    write("t_standin", r"Quality of the differentiable stand-ins ($R^2$ against the true score, mean over seeds): A8 for "
          r"D$_+$ and the Stage B attackers of a1 and a2.", "t_standin", "lcccccc",
          [["", r"\multicolumn{2}{c}{A8 (D$_+$)}", r"\multicolumn{2}{c}{a1}", r"\multicolumn{2}{c}{a2}"],
           ["Consistency score", "2017", "2018", "2017", "2018", "2017", "2018"]], rows,
          ["results/stage8/stage8c_standin_quality_2017.csv", "results/stage7/stage7e/standin_quality.csv",
           "results/stage9/adaptive/{2017,2018}/standin_quality.csv"],
          ["Validation rows of each seed. a1 and a2: the 12 consistency columns of the control (x0 to x11, in the order "
           "of D$_+$); their four D features are exact. The last row covers the 12 consistency scores only, so it can "
           "differ from the $R^2$ in Table~\\ref{t_union_adaptive}, which also covers the four exact D features. c0, c1 "
           "and c2 are attacked with exact gradients."], resize="shrink", tabcolsep=4)


